"""Basic statistics. These are stubs — implement them so the tests pass."""


def mean(xs):
    """Arithmetic mean of a non-empty list of numbers."""
    return sum(xs) / len(xs)


def median(xs):
    """Median of a non-empty list of numbers (average of the two middle values
    when the length is even). Input is not guaranteed to be sorted."""
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    mid = n // 2
    if n % 2 == 0:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2
    else:
        return sorted_xs[mid]
